const { renderSVG } = require('/usr/local/lib/node_modules/@antv/infographic');
const fs = require('fs');
const path = require('path');

const syntax = `infographic list-waterfall-badge-card
data
  title PYPL Programming Language Popularity Index
  desc April 2026  ·  Google Trends Tutorial Search Analysis  ·  30 Languages Tracked
  lists
    - label Python
      value 36.21
      desc #1  ·  +5.7% YoY  ·  Dominant Leader
    - label C/C++
      value 13.21
      desc #2  ·  +6.2% YoY  ·  Biggest Gainer
    - label Java
      value 10.01
      desc #3  ·  -5.4% YoY  ·  Steepest Decline
    - label R
      value 6.17
      desc #4  ·  +1.6% YoY  ·  Data Science Demand
    - label JavaScript
      value 5.07
      desc #5  ·  -3.0% YoY  ·  Under Pressure
    - label Swift
      value 3.15
      desc #6  ·  +0.8% YoY  ·  Steady Growth
    - label C#
      value 3.00
      desc #7  ·  -3.0% YoY  ·  Declining
    - label Rust
      value 2.98
      desc #8  ·  -0.1% YoY  ·  Stable
    - label PHP
      value 2.96
      desc #9  ·  -0.7% YoY  ·  Gradual Decline
    - label Objective-C
      value 2.57
      desc #10  ·  +0.1% YoY  ·  Niche Stable
theme
  palette #0ea5e9 #22c55e #3b82f6 #f97316 #8b5cf6 #ef4444
`;

async function main() {
  try {
    const svg = await renderSVG(syntax, { width: 800 });
    const outPath = '/app/output/poster.svg';
    fs.mkdirSync('/app/output', { recursive: true });
    fs.writeFileSync(outPath, svg);
    console.log('SVG written to', outPath);
    console.log('SVG length:', svg.length);
  } catch (err) {
    console.error('Error:', err.message);
    process.exit(1);
  }
}

main();

